var a2 = { versao: "16.19.1", campeao: { nome: "Campeao53", titulo: "a M\xE3o de Cidade04", lore: "N\xE3o h\xE1 s\xEDmbolo maior do poder de Cidade04 do que Campeao53, o mais temido e experiente comandante da na\xE7\xE3o. Vindo de origens humildes para se tornar a M\xE3o de Cidade04, ele corta seu caminho atrav\xE9s dos inimigos do imp\xE9rio; muitos dos quais s\xE3o, inclusive, noxianos. Sabendo que ele nunca duvida da integridade de sua causa e que nunca hesita assim que seu machado \xE9 levantado, aqueles que desafiam o comandante da Legi\xE3o Trifariana n\xE3o esperam por miseric\xF3rdia.", stats: { hp: 652, hpperlevel: 114, mp: 263, mpperlevel: 58, movespeed: 340, armor: 37, armorperlevel: 5.2, spellblock: 32, spellblockperlevel: 2.05, attackrange: 175, hpregen: 10, hpregenperlevel: 0.95, mpregen: 6.6, mpregenperlevel: 0.35, crit: 0, critperlevel: 0, attackdamage: 64, attackdamageperlevel: 0, attackspeedperlevel: 1, attackspeed: 0.625 } }, habilidades: { P: { nome: "Hemorragia", descricao: "Os Ataques e Habilidades de dano de Campeao53 fazem os inimigos sangrarem, causando Dano F\xEDsico ao longo de 5s e acumulando at\xE9 5 vezes. Campeao53 se enfurece e recebe uma grande quantidade de Dano de Ataque quando o alvo alcan\xE7a o m\xE1ximo de ac\xFAmulos." }, Q: { nome: "Dizimar", descricao: "Campeao53 pega impulso e golpeia com seu machado em um movimento circular. Os inimigos atingidos pela l\xE2mina recebem mais dano do que aqueles atingidos pelo cabo. Campeao53 cura a si mesmo com base nos Campe\xF5es inimigos e monstros grandes atingidos pela l\xE2mina.", recarga: [9, 8, 7, 6, 5] }, W: { nome: "Ataque Mutilador", descricao: "O pr\xF3ximo ataque de Campeao53 acerta uma art\xE9ria importante do inimigo. Enquanto a v\xEDtima sangra, a Velocidade de Movimento dela \xE9 reduzida.", recarga: [5, 5, 5, 5, 5] }, E: { nome: "Apreender", descricao: "Campeao53 afia seu machado, fazendo com que seu Dano F\xEDsico ignore passivamente um percentual da Armadura do alvo. Quando ativado, Campeao53 ataca seus inimigos com o gancho do seu machado e os puxa em sua dire\xE7\xE3o.", recarga: [26, 23.5, 21, 18.5, 16] }, R: { nome: "Guilhotina de Cidade04", descricao: "Campeao53 salta na dire\xE7\xE3o de um Campe\xE3o inimigo e o atinge com um golpe letal, causando Dano Verdadeiro. Este dano aumenta a cada ac\xFAmulo de Hemorragia no alvo. Se Guilhotina de Cidade04 causar o golpe final, seu Tempo de Recarga \xE9 zerado por um breve momento.", recarga: [120, 100, 80] } }, skins: [{ num: 0, nome: "Campeao53" }, { num: 1, nome: "Lorde Campeao53" }, { num: 2, nome: "Campeao53 Bioforja" }, { num: 3, nome: "Campeao53 Rei dos Bret\xF5es" }, { num: 4, nome: "Campeao53 Mestre da Enterrada" }, { num: 8, nome: "Campeao53 Colegial" }, { num: 14, nome: "Campeao53 Nova Tem\xEDvel" }, { num: 15, nome: "Deus-Rei Campeao53" }, { num: 16, nome: "Campeao53 Velho Oeste" }, { num: 24, nome: "Campeao53 Fera Lunar" }, { num: 33, nome: "Campeao53 Pesadelo na Cidade do Crime" }, { num: 43, nome: "Campeao53 Florescer Espiritual" }, { num: 54, nome: "Campeao53 de Porcelana" }, { num: 64, nome: "Deus-Rei Campeao53 Divino" }, { num: 65, nome: "Campeao53 General Triunfante de Prest\xEDgio" }, { num: 67, nome: "Campeao53 Reinos Mech" }], itens: [{ id: "1036", nome: "Espada Longa", preco: 350, resumo: "Aumenta levemente o Dano de Ataque", ad: 10, vida: 0, armadura: 0, rm: 0, va: 0, rv: 0, efeito: null, lendario: false }, { id: "1028", nome: "Cristal de Rubi", preco: 400, resumo: "Aumenta a Vida", ad: 0, vida: 150, armadura: 0, rm: 0, va: 0, rv: 0, efeito: null, lendario: false }, { id: "1029", nome: "Coura\xE7a de Pano", preco: 300, resumo: "Aumenta levemente a Armadura", ad: 0, vida: 0, armadura: 15, rm: 0, va: 0, rv: 0, efeito: null, lendario: false }, { id: "1042", nome: "Adaga", preco: 250, resumo: "Aumenta levemente a Velocidade de Ataque", ad: 0, vida: 0, armadura: 0, rm: 0, va: 0.1, rv: 0, efeito: null, lendario: false }, { id: "1037", nome: "Picareta", preco: 875, resumo: "Aumenta moderadamente o Dano de Ataque", ad: 25, vida: 0, armadura: 0, rm: 0, va: 0, rv: 0, efeito: null, lendario: false }, { id: "3044", nome: "Fago", preco: 1100, resumo: "Ataques e abates d\xE3o um efeito curto de velocidade", ad: 15, vida: 200, armadura: 0, rm: 0, va: 0, rv: 0, efeito: "F\xFAria: cada ataque b\xE1sico d\xE1 +8% de Velocidade de Ataque por 2s.", lendario: false }, { id: "6631", nome: "Quebrapassos", preco: 3300, resumo: "", ad: 40, vida: 450, armadura: 0, rm: 0, va: 0.25, rv: 0, efeito: "Golpe Pesado: a cada 5s, o pr\xF3ximo ataque causa +80% do Dano de Ataque em todos os inimigos.", lendario: true }, { id: "3071", nome: "Cutelo Negro", preco: 3e3, resumo: "Causar dano f\xEDsico reduz Armadura de Campe\xF5es inimigos", ad: 45, vida: 400, armadura: 0, rm: 0, va: 0, rv: 0, efeito: "Talhar: cada ataque reduz a Armadura do alvo em 6%, acumulando at\xE9 30%.", lendario: true }, { id: "3053", nome: "Sinal de Sterak", preco: 3200, resumo: "Protege contra fortes rajadas de dano", ad: 0, vida: 400, armadura: 0, rm: 0, va: 0, rv: 0, efeito: "Pele de A\xE7o: com menos de 30% de Vida, ganha um escudo de 60% da Vida b\xF4nus (a cada 90s).", lendario: true }, { id: "3742", nome: "Coura\xE7a do Defunto", preco: 2900, resumo: "Acumula Embalo com a movimenta\xE7\xE3o, descarregando-o em inimigos", ad: 0, vida: 350, armadura: 55, rm: 0, va: 0, rv: 0, efeito: "Rolo Compressor: a cada 4s, o pr\xF3ximo ataque causa +40 de dano.", lendario: true }, { id: "3078", nome: "For\xE7a da Trindade", preco: 3333, resumo: "Toneladas de dano", ad: 36, vida: 333, armadura: 0, rm: 0, va: 0.3, rv: 0, efeito: "L\xE2mina Encantada: depois de usar uma habilidade, o pr\xF3ximo ataque causa +200% do Dano de Ataque base.", lendario: true }, { id: "6333", nome: "Dan\xE7a da Morte", preco: 3300, resumo: "", ad: 60, vida: 0, armadura: 50, rm: 0, va: 0, rv: 0, efeito: "Ignorar a Dor: 30% do dano recebido vira sangramento ao longo de 3s. Ao abater, limpa o sangramento e cura 15% da Vida perdida.", lendario: true }, { id: "2501", nome: "Armadura Sangrenta do Suserano", preco: 3300, resumo: "", ad: 30, vida: 550, armadura: 0, rm: 0, va: 0, rv: 0, efeito: "Tirania: ganha Dano de Ataque igual a 2% da Vida b\xF4nus.", lendario: true }, { id: "3748", nome: "Hidra Tit\xE2nica", preco: 3300, resumo: "Causa dano em \xE1rea com base na vida de seu dono", ad: 40, vida: 600, armadura: 0, rm: 0, va: 0, rv: 0, efeito: "Cleave Tit\xE2nico: ataques causam +1,5% da Vida m\xE1xima em todos os inimigos encostados no Campeao53.", lendario: true }, { id: "3074", nome: "Hidra Raivosa", preco: 3300, resumo: "Ataques corpo a corpo atingem inimigos pr\xF3ximos, causando dano restaurando Vida", ad: 65, vida: 0, armadura: 0, rm: 0, va: 0, rv: 0.12, efeito: "Cleave: ataques causam 40% do Dano de Ataque nos outros inimigos. Roubo de vida de 12%.", lendario: true }, { id: "3075", nome: "Armadura de Espinhos", preco: 2450, resumo: "", ad: 0, vida: 150, armadura: 75, rm: 0, va: 0, rv: 0, efeito: "Espinhos: quem ataca Campeao53 recebe 10 + 10% da Armadura b\xF4nus como dano.", lendario: true }, { id: "6610", nome: "C\xE9u Dividido", preco: 3100, resumo: "", ad: 40, vida: 400, armadura: 0, rm: 0, va: 0, rv: 0, efeito: "Choque de Luz: o primeiro ataque em cada inimigo \xE9 cr\xEDtico e cura 6% da Vida perdida.", lendario: true }, { id: "3065", nome: "Semblante Espiritual", preco: 2700, resumo: "Aumenta a Vida e efeitos de cura", ad: 0, vida: 400, armadura: 0, rm: 50, va: 0, rv: 0, efeito: "Vitalidade Ilimitada: +25% em toda cura recebida.", lendario: true }, { id: "3026", nome: "Anjo Guardi\xE3o", preco: 3200, resumo: "Periodicamente ressuscita um campe\xE3o ao morrer", ad: 55, vida: 0, armadura: 45, rm: 0, va: 0, rv: 0, efeito: "Renascimento: ao morrer, volta com 50% da Vida (a cada 300s).", lendario: true }] };

