var e = { versao: "16.19.1", campeao: { nome: "Campeao55", titulo: "o Explorador Pr\xF3digo", lore: "Um aventureiro arrojado, com um talento nato nas artes m\xE1gicas, Campeao55 desbrava catacumbas soterradas, envolve-se com antigas maldi\xE7\xF5es e supera com facilidade as situa\xE7\xF5es mais improv\xE1veis. Sua coragem e ousadia n\xE3o t\xEAm limites e ele prefere resolver as coisas no improviso, confiando parcialmente no seu talento, mas principalmente em sua m\xEDstica luva shurimane, que ele usa para causar explos\xF5es arcanas devastadoras. Uma coisa \xE9 certa: quando Campeao55 est\xE1 por perto, l\xE1 vem problema. Ou l\xE1 vai. Ou j\xE1 veio.", stats: { hp: 600, hpperlevel: 102, mp: 375, mpperlevel: 70, movespeed: 325, armor: 24, armorperlevel: 4.2, spellblock: 33, spellblockperlevel: 1.1, attackrange: 550, hpregen: 4, hpregenperlevel: 0.65, mpregen: 8.5, mpregenperlevel: 1, crit: 0, critperlevel: 0, attackdamage: 60, attackdamageperlevel: 0, attackspeedperlevel: 2.5, attackspeed: 0.625 }, funcoes: ["Marksman", "Mage"] }, habilidades: { P: { nome: "Feiti\xE7o do Poder Crescente", descricao: "Campeao55 recebe Velocidade de Ataque crescente a cada vez que acerta uma habilidade, acumulando-se at\xE9 5 vezes." }, Q: { nome: "Disparo M\xEDstico", descricao: "Campeao55 faz um disparo de energia que reduz um pouco o Tempo de Recarga de todas as suas habilidades caso atinja uma unidade inimiga.", recarga: [5.5, 5.25, 5, 4.75, 4.5] }, W: { nome: "Fluxo Essencial", descricao: "Campeao55 dispara um orbe que prende-se ao primeiro Campe\xE3o ou objetivo atingido. Caso atinja um inimigo preso com o orbe, ele detonar\xE1 e causar\xE1 dano.", recarga: [8, 8, 8, 8, 8] }, E: { nome: "Transloca\xE7\xE3o Arcana", descricao: "Campeao55 teleporta-se para um local-alvo pr\xF3ximo e faz um disparo teleguiado na unidade inimiga mais pr\xF3xima. Prioriza inimigos atingidos com Fluxo Essencial.", recarga: [26, 23, 20, 17, 14] }, R: { nome: "Barragem Incendi\xE1ria", descricao: "Campeao55 carrega antes de disparar uma poderosa barragem de energia que causa dano massivo em cada unidade que atravessar (o dano \xE9 reduzido contra tropas e monstros n\xE3o \xE9picos).", recarga: [120, 105, 90] } }, skins: [{ num: 0, nome: "Campeao55" }, { num: 1, nome: "Campeao55 de Nottingham" }, { num: 2, nome: "Campeao55 Atacante" }, { num: 3, nome: "Campeao55 G\xE9lido" }, { num: 4, nome: "Campeao55 Explorador" }, { num: 5, nome: "Pulsefire Campeao55" }, { num: 7, nome: "Campeao55 Galante" }, { num: 8, nome: "Campeao55 \xC1s de Espadas" }, { num: 9, nome: "Campeao55 Fliperama" }, { num: 18, nome: "Campeao55 Guardi\xE3o Estelar" }, { num: 19, nome: "SSG Campeao55" }, { num: 21, nome: "Campeao55 Academia de Batalha" }, { num: 22, nome: "Campeao55 PsyOps" }, { num: 25, nome: "Campeao55 Protetor de Porcelana" }, { num: 33, nome: "Campeao55 Corte das Fadas" }, { num: 43, nome: "Campeao55 HEARTSTEEL" }, { num: 44, nome: "Campeao55 Escamas Celestiais" }, { num: 54, nome: "Campeao55 Escamas Celestiais de Prest\xEDgio" }] };

