var e2 = { versao: "16.19.1", campeao: { nome: "Campeao124", titulo: "o Imperdo\xE1vel", lore: "Campeao124, um ioniano extremamente determinado, \xE9 tamb\xE9m um \xE1gil espadachim que usa o pr\xF3prio ar como arma para enfrentar seus inimigos. Quando jovem, ele teve seu orgulho ferido ao ser acusado injustamente do assassinato de seu mestre \u2014 sem conseguir provar sua inoc\xEAncia, ele foi for\xE7ado a matar o pr\xF3prio irm\xE3o para se defender. At\xE9 hoje, mesmo depois do verdadeiro assassino do seu mestre ter sido revelado, Campeao124 ainda n\xE3o consegue se perdoar e vaga por sua terra natal com apenas o vento para guiar sua espada.", stats: { hp: 590, hpperlevel: 110, mp: 100, mpperlevel: 0, movespeed: 345, armor: 32, armorperlevel: 4.6, spellblock: 32, spellblockperlevel: 2.05, attackrange: 175, hpregen: 6.5, hpregenperlevel: 0.9, mpregen: 0, mpregenperlevel: 0, crit: 0, critperlevel: 0, attackdamage: 60, attackdamageperlevel: 0, attackspeedperlevel: 3.5, attackspeed: 0.697 }, funcoes: ["Fighter", "Assassin"] }, habilidades: { P: { nome: "Estilo do Errante", descricao: "A Chance de Acerto Cr\xEDtico do Campeao124 \xE9 aumentada. Al\xE9m disso, Campeao124 vai gerando um Escudo sempre que se movimenta. O Escudo \xE9 ativado quando Campeao124 sofre dano de um Campe\xE3o ou monstro." }, Q: { nome: "Tempestade de A\xE7o", descricao: "Golpeia \xE0 frente, causando dano a todos os inimigos em linha reta. Ao contato, Tempestade de A\xE7o concede um ac\xFAmulo de Tempestade Crescente por alguns segundos. Com 2 ac\xFAmulos, Tempestade de A\xE7o desfere um tornado que arremessa inimigos ao ar. Tempestade de A\xE7o \xE9 tratada como ataque b\xE1sico e escala com as mesmas coisas.", recarga: [4, 4, 4, 4, 4] }, W: { nome: "Parede de Vento", descricao: "Cria uma parede movedi\xE7a que bloqueia todos os proj\xE9teis inimigos por 4 segundos.", recarga: [25, 23, 21, 19, 17] }, E: { nome: "Espada \xC1gil", descricao: "Avan\xE7a e atravessa o inimigo-alvo, causando Dano M\xE1gico. Cada conjura\xE7\xE3o aumenta o dano do pr\xF3ximo avan\xE7o, at\xE9 um limite m\xE1ximo. N\xE3o pode ser conjurada novamente no mesmo inimigo por alguns segundos. Se Tempestade de A\xE7o for conjurada durante o avan\xE7o, o Ataque ser\xE1 circular.", recarga: [0.5, 0.4, 0.3, 0.2, 0.1] }, R: { nome: "\xDAltimo Suspiro", descricao: "Teletransporta-se para um Campe\xE3o inimigo arremessado ao ar, causando Dano F\xEDsico e mantendo no ar todos os inimigos da \xE1rea que foram arremessados ao ar. Concede o m\xE1ximo de Fluxo, mas zera todos os ac\xFAmulos de Tempestade Crescente Por um per\xEDodo moderado a seguir, os Acertos Cr\xEDticos de Campeao124 recebem Penetra\xE7\xE3o de Armadura adicional significativa.", recarga: [70, 50, 30] } }, skins: [{ num: 0, nome: "Campeao124" }, { num: 3, nome: "Campeao124 Lua Sangrenta" }, { num: 9, nome: "Campeao124 Emiss\xE1rio da Escurid\xE3o" }, { num: 36, nome: "Campeao124 Florescer Espiritual" }, { num: 54, nome: "Campeao124 Drag\xE3o da Verdade" }] };

