var a3 = { versao: "16.19.1", campeao: { nome: "Campeao154", titulo: "a Dama da Luz", lore: "Luxanna Stemmaguarda nasceu em Cidade03, um reino insular onde habilidades m\xE1gicas s\xE3o vistas com medo e desconfian\xE7a. Capaz de dobrar a luz \xE0 sua vontade, ela cresceu temendo ser descoberta e exilada, e foi for\xE7ada a manter seus poderes em segredo a fim de preservar o status de nobreza de sua fam\xEDlia. Apesar de tudo, o otimismo e resili\xEAncia de Campeao154 a levaram a aceitar seus talentos \xFAnicos e agora ela os utiliza em segredo a servi\xE7o de sua terra natal.", stats: { hp: 580, hpperlevel: 99, mp: 440, mpperlevel: 23.5, movespeed: 330, armor: 21, armorperlevel: 5.2, spellblock: 30, spellblockperlevel: 1.3, attackrange: 550, hpregen: 5.5, hpregenperlevel: 0.55, mpregen: 9, mpregenperlevel: 0.8, crit: 0, critperlevel: 0, attackdamage: 54, attackdamageperlevel: 0, attackspeedperlevel: 3, attackspeed: 0.669 }, funcoes: ["Mage", "Support"] }, habilidades: { P: { nome: "Ilumina\xE7\xE3o", descricao: "As habilidades de dano de Campeao154 carregam o alvo com energia por alguns segundos. O pr\xF3ximo ataque de Campeao154 incendeia a energia, causando Dano M\xE1gico adicional (com base no n\xEDvel de Campeao154) ao alvo." }, Q: { nome: "Liga\xE7\xE3o da Luz", descricao: "Campeao154 atira uma esfera de luz que se prende e causa dano em at\xE9 duas unidades inimigas.", recarga: [10, 10, 10, 10, 10] }, W: { nome: "Barreira Prism\xE1tica", descricao: "Campeao154 lan\xE7a sua varinha e uma luz envolve todos os aliados atingidos, protegendo-os contra dano inimigo.", recarga: [12, 11.5, 11, 10.5, 10] }, E: { nome: "Singularidade Lucente", descricao: "Dispara uma luz irregular em uma \xE1rea, reduzindo a velocidade de inimigos pr\xF3ximos. Campeao154 pode deton\xE1-la para causar dano aos inimigos na \xE1rea de a\xE7\xE3o.", recarga: [10, 9.5, 9, 8.5, 8] }, R: { nome: "Centelha Final", descricao: "Ap\xF3s acumular energia, Campeao154 dispara um feixe de luz que causa dano a todos os inimigos na \xE1rea. Al\xE9m disso, ativa a habilidade passiva de Campeao154 e reinicia a dura\xE7\xE3o do efeito de Ilumina\xE7\xE3o.", recarga: [60, 50, 40] } }, skins: [{ num: 0, nome: "Campeao154" }, { num: 6, nome: "Campeao154 Guardi\xE3 Estelar" }, { num: 7, nome: "Campeao154 Elementalista" }, { num: 15, nome: "Campeao154 Academia de Batalha" }, { num: 42, nome: "Campeao154 Emp\xEDrea" }] };

