var a4 = { versao: "16.19.1", campeao: { nome: "Campeao19", titulo: "a L\xE2mina Sinistra", lore: "Decisiva em seus julgamentos e letal em combate, Campeao19 \xE9 a assassina de maior calibre de Cidade04. Filha mais velha do lend\xE1rio General Du Couteau, Campeao19 \xE9 reconhecida por seus assassinatos eficientes contra inimigos desavisados. Sua ambi\xE7\xE3o ardente a levou a buscar alvos extremamente protegidos, mesmo correndo o risco de colocar seus aliados em perigo; mas n\xE3o importa a miss\xE3o, Campeao19 n\xE3o hesita ao executar seu dever no meio de um furac\xE3o de adagas serrilhadas.", stats: { hp: 672, hpperlevel: 108, mp: 0, mpperlevel: 0, movespeed: 335, armor: 32, armorperlevel: 4.7, spellblock: 32, spellblockperlevel: 2.05, attackrange: 125, hpregen: 7.5, hpregenperlevel: 0.7, mpregen: 0, mpregenperlevel: 0, crit: 0, critperlevel: 0, attackdamage: 58, attackdamageperlevel: 0, attackspeedperlevel: 2.74, attackspeed: 0.658 }, funcoes: ["Assassin", "Mage"] }, habilidades: { P: { nome: "Voracidade", descricao: "Cada monstro que Campeao19 abate tira 1,5 s da recarga da L\xE2mina Saltitante, da Prepara\xE7\xE3o e do Shunpo (5 s se for um chefe). As habilidades extras n\xE3o t\xEAm a recarga reduzida. Se apanhar uma Adaga, Campeao19 a usa para cortar todos os inimigos pr\xF3ximos, causando Dano M\xE1gico." }, Q: { nome: "L\xE2mina Saltitante", descricao: "Campeao19 arremessa uma Adaga no alvo. Ela salta em inimigos pr\xF3ximos antes de ricochetear e cair no ch\xE3o.", recarga: [11, 10, 9, 8, 7] }, W: { nome: "Prepara\xE7\xE3o", descricao: "Campeao19 recebe um impulso de Velocidade de Movimento e joga uma Adaga para cima.", recarga: [15, 14, 13, 12, 11] }, E: { nome: "Shunpo", descricao: "Campeao19 desloca-se em dire\xE7\xE3o ao alvo, golpeando-o caso seja inimigo ou golpeando o inimigo mais pr\xF3ximo caso n\xE3o seja.", recarga: [12, 11, 10, 9, 8] }, R: { nome: "L\xF3tus da Morte", descricao: "Campeao19 gira em torno de si mesma, disparando adagas muito rapidamente e causando muito Dano M\xE1gico nos 3 Campe\xF5es inimigos mais pr\xF3ximos.", recarga: [75, 60, 45] } }, skins: [{ num: 0, nome: "Campeao19" }, { num: 10, nome: "Campeao19 Jurada de Morte" }, { num: 12, nome: "Campeao19 Academia de Batalha" }, { num: 29, nome: "Campeao19 Rainha de Batalha" }, { num: 48, nome: "Campeao19 Corte das Fadas de Prest\xEDgio" }] };

// dados-Campeao117.js
var a5 = { versao: "16.19.1", campeao: { nome: "Campeao117", titulo: "o Escudo de Valoran", lore: "Campeao117 \xE9 o Aspecto do Protetor, portando um incr\xEDvel poder como o guardi\xE3o da vida, do amor e da beleza de Mundo. Punido por faltar ao cumprimento de seu dever e exilado de Cidade03, sua terra natal, Campeao117 subiu o Monte Cidade10 em busca de reden\xE7\xE3o, mas acabou por descobrir um chamado maior dentre as estrelas. Imbu\xEDdo do poder ancestral de Cidade10, o Escudo de Valoran agora mant\xE9m vigil\xE2ncia contra a p\xE9rfida corrup\xE7\xE3o do Vazio.", stats: { hp: 645, hpperlevel: 99, mp: 300, mpperlevel: 60, movespeed: 340, armor: 40, armorperlevel: 4.3, spellblock: 28, spellblockperlevel: 2.05, attackrange: 150, hpregen: 6, hpregenperlevel: 0.5, mpregen: 8.5, mpregenperlevel: 0.8, crit: 0, critperlevel: 0, attackdamage: 55, attackdamageperlevel: 0, attackspeedperlevel: 2, attackspeed: 0.625 }, funcoes: ["Support", "Tank"] }, habilidades: { P: { nome: "Bravata", descricao: "Conjura\xE7\xF5es fortalecem os pr\xF3ximos 2 ataques b\xE1sicos de Campeao117, causando Dano M\xE1gico adicional, reduzindo Tempos de Recarga e atacando em r\xE1pida sucess\xE3o." }, Q: { nome: "Fulgor Estelar", descricao: "Cura Campe\xF5es aliados pr\xF3ximos com base nas cargas armazenadas. Ataques fortalecidos por Bravata concedem uma carga de Fulgor Estelar.", recarga: [3, 3, 3, 3, 3] }, W: { nome: "Basti\xE3o", descricao: "Aumenta passivamente a Armadura de Campeao117 e de qualquer Campe\xE3o aliado com Basti\xE3o. Protege ativamente um aliado e lhe concede Basti\xE3o por todo o tempo que permanecer pr\xF3ximo a Campeao117. As habilidades de Campeao117 tamb\xE9m s\xE3o conjuradas a partir do aliado com Basti\xE3o.", recarga: [15, 15, 15, 15, 15] }, E: { nome: "Deslumbrar", descricao: "Campeao117 prepara um feixe de luz estelar que, ap\xF3s um breve intervalo, causa Dano M\xE1gico e atordoa inimigos.", recarga: [16, 15, 14, 13, 12] }, R: { nome: "Resplendor C\xF3smico", descricao: "Faz pulsar energia c\xF3smica em Campe\xF5es aliados pr\xF3ximos ap\xF3s um intervalo, tornando-os invulner\xE1veis por um curto per\xEDodo.", recarga: [180, 150, 120] } }, skins: [{ num: 0, nome: "Campeao117" }, { num: 1, nome: "Campeao117 Esmeralda" }, { num: 3, nome: "Campeao117 Cavaleiro de Hematita" }, { num: 18, nome: "Campeao117 Embalos no Espa\xE7o" }, { num: 27, nome: "Campeao117 Subversor de Destinos" }] };

// dados-Campeao155.js
var e3 = { versao: "16.19.1", campeao: { nome: "Campeao155", titulo: "a Arma Secreta", lore: "Campeao155 \xE9 produto de um derramamento t\xF3xico que percorreu um tubo quimtec e se armazenou em uma caverna isolada no Sumidouro de Cidade02. Apesar de suas origens humildes, Campeao155 deixou de ser uma lama qualquer e se tornou um ser pensante que mora nos encanamentos da cidade e emerge ocasionalmente para ajudar aqueles que n\xE3o podem se ajudar ou para reconstruir a infraestrutura danificada de Cidade02.", stats: { hp: 685, hpperlevel: 109, mp: 0, mpperlevel: 0, movespeed: 340, armor: 33, armorperlevel: 5.2, spellblock: 32, spellblockperlevel: 2.05, attackrange: 175, hpregen: 5, hpregenperlevel: 0.5, mpregen: 0, mpregenperlevel: 0, crit: 0, critperlevel: 0, attackdamage: 60, attackdamageperlevel: 0, attackspeedperlevel: 1.6, attackspeed: 0.736 }, funcoes: ["Tank", "Fighter"] }, habilidades: { P: { nome: "Divis\xE3o Celular", descricao: "Sempre que Campeao155 atinge um inimigo com uma habilidade, ele perde parte de si mesmo que pode ser reabsorvida para restaurar Vida. Ao receber dano letal, Campeao155 divide-se em 4 peda\xE7os que tentam se recombinar. Se qualquer peda\xE7o permanecer, ele ressuscitar\xE1 uma quantia de Vida, dependendo da vida dos peda\xE7os sobreviventes. Cada peda\xE7o tem um percentual da Vida m\xE1xima de Campeao155, de sua Armadura e de Resist\xEAncia M\xE1gica. Essa habilidade tem 5 minutos de Tempo de Recarga." }, Q: { nome: "Esticada", descricao: "Campeao155 estica um bra\xE7o, agarrando um inimigo. Atacar um inimigo diferente o far\xE1 arremessar ambos os alvos na dire\xE7\xE3o um do outro.", recarga: [14, 12.5, 11, 9.5, 8] }, W: { nome: "Mat\xE9ria Inst\xE1vel", descricao: "Campeao155 explode para fora em dire\xE7\xE3o a inimigos pr\xF3ximos, causando um percentual de suas Vidas m\xE1ximas como Dano M\xE1gico.", recarga: [5, 5, 5, 5, 5] }, E: { nome: "Estilingue El\xE1stico", descricao: "Campeao155 segura o ch\xE3o com seus bra\xE7os e se estica para tr\xE1s, lan\xE7ando-se para frente.", recarga: [21, 18, 15, 12, 9] }, R: { nome: "Vamos pular!", descricao: "Campeao155 pula quatro vezes, arremessando inimigos atingidos ao ar e reduzindo a velocidade deles.", recarga: [120, 105, 90] } }, skins: [{ num: 0, nome: "Campeao155" }, { num: 1, nome: "Campeao155 Arma Especial" }, { num: 14, nome: "Campeao155 Emp\xEDreo" }, { num: 24, nome: "Campeao155 Molho Picante" }] };

// dados-Campeao145.js
var e4 = { versao: "16.19.1", campeao: { nome: "Campeao145", titulo: "o Mago R\xFAnico", lore: "Considerado pela grande maioria como o mago mais habilidoso de Mundo, Campeao145 \xE9 um arquimago anci\xE3o e amargo que carrega um enorme peso. Dotado de um enorme poder arcano e de uma not\xE1vel estrutura f\xEDsica, ele busca incansavelmente pelas Runas Globais, que s\xE3o fragmentos de magia pura que um dia criaram o mundo a partir do nada. Ele deve recuperar esses artefatos antes que eles caiam em m\xE3os erradas, pois Campeao145 conhece bem os horrores que eles podem infligir em Mundo.", stats: { hp: 620, hpperlevel: 124, mp: 300, mpperlevel: 70, movespeed: 340, armor: 22, armorperlevel: 4.7, spellblock: 32, spellblockperlevel: 1.3, attackrange: 550, hpregen: 8, hpregenperlevel: 0.8, mpregen: 8, mpregenperlevel: 1, crit: 0, critperlevel: 0, attackdamage: 55, attackdamageperlevel: 0, attackspeedperlevel: 2.11, attackspeed: 0.658 }, funcoes: ["Mage"] }, habilidades: { P: { nome: "Maestria Arcana", descricao: "As habilidades de Campeao145 causam dano adicional com base em seu Mana adicional. Ele recebe um percentual de aumento de Mana m\xE1ximo com base em seu Poder de Habilidade." }, Q: { nome: "Sobrecarregar", descricao: "Passivamente, as outras habilidades b\xE1sicas de Campeao145 redefinem o Tempo de Recarga de Sobrecarregar e carregam uma runa. Quando Campeao145 conjura Sobrecarregar com 2 runas carregadas, ele recebe um breve surto de Velocidade de Movimento. Ao conjurar, Campeao145 arremessa uma carga de energia pura em linha reta, causando dano ao primeiro inimigo atingido. Se o alvo estiver afetado por Fluxo, Sobrecarregar causa dano adicional e rebate para inimigos pr\xF3ximos atingidos por Fluxo.", recarga: [5, 5, 5, 5, 5] }, W: { nome: "Pris\xE3o de Runa", descricao: "Campeao145 prende um alvo em uma pris\xE3o de runas, causando dano e reduzindo sua Velocidade de Movimento. Se o alvo estiver afetado por Fluxo, ele \xE9 enraizado.", recarga: [11, 10.5, 10, 9.5, 9] }, E: { nome: "Fluxo de Feiti\xE7o", descricao: "Campeao145 lan\xE7a um orbe de puro poder m\xE1gico que causa dano a um inimigo e um efeito negativo em todos os inimigos pr\xF3ximos. As habilidades de Campeao145 t\xEAm efeitos adicionais contra a unidade afetada.", recarga: [3.5, 3.25, 3, 2.75, 2.5] }, R: { nome: "Portal de Reinos", descricao: "Passivamente, Sobrecarregar causa ainda mais dano contra alvos afetados por Fluxo. Ao conjurar, Campeao145 cria um portal para um local pr\xF3ximo. Ap\xF3s alguns segundos, aliados pr\xF3ximos ao portal s\xE3o teleportados ao local alvo.", recarga: [180, 160, 140] } }, skins: [{ num: 0, nome: "Campeao145" }, { num: 9, nome: "Campeao145 Barba Branca" }, { num: 13, nome: "Campeao145 Guardi\xE3o das Areias" }, { num: 20, nome: "Campeao145 Arcana" }] };

// dados-Campeao17.js
var a6 = { versao: "16.19.1", campeao: { nome: "Campeao17", titulo: "a Arma dos Devotos", lore: "Emergindo da sombra do luar com suas armas em m\xE3os, Campeao17 abate os inimigos de sua f\xE9 em absoluto sil\xEAncio, comunicando-se apenas pela destreza de sua mira e pelo disparo de cada arma. Embora viva sob o efeito de um veneno que o emudeceu, ele \xE9 guiado por sua irm\xE3 Alune, que habita um santu\xE1rio distante de onde invoca um arsenal de armas de pedra da lua para ajud\xE1-lo. Enquanto a lua brilhar no c\xE9u, Campeao17 nunca estar\xE1 sozinho.", stats: { hp: 600, hpperlevel: 102, mp: 348, mpperlevel: 42, movespeed: 325, armor: 26, armorperlevel: 4.2, spellblock: 33, spellblockperlevel: 1.1, attackrange: 550, hpregen: 3.25, hpregenperlevel: 0.55, mpregen: 6.5, mpregenperlevel: 0.4, crit: 0, critperlevel: 0, attackdamage: 55, attackdamageperlevel: 0, attackspeedperlevel: 2.1, attackspeed: 0.665 }, funcoes: ["Marksman"] }, habilidades: { P: { nome: "O Assassino e a Profetisa", descricao: "Campeao17 empunha 5 Armas Lunari criadas por sua irm\xE3, Alune. Ele tem acesso a duas ao mesmo tempo: uma principal e uma secund\xE1ria. Cada arma tem um ataque b\xE1sico e uma Habilidade \xFAnicos. Ataques e habilidades consomem uma muni\xE7\xE3o da arma. Quando fica sem muni\xE7\xE3o, Campeao17 descarta a arma e Alune invoca a pr\xF3xima." }, Q: { nome: "Habilidades da arma", descricao: "Campeao17 tem 5 habilidades diferentes que s\xE3o ativadas com base em sua arma principal: Calibrum (Rifle): Tiro de longo alcance que marca seu alvo para um disparo de longo alcance subsequente. Severum (Pistola-Foice): Corre rapidamente enquanto ataca inimigos pr\xF3ximos com ambas as armas. Gravitum (Canh\xE3o): Enra\xEDza todos os inimigos afetados pela redu\xE7\xE3o de velocidade desta arma. Infernum (Lan\xE7a-chamas): Explode inimigos em \xE1rea de cone e os ataca com sua arma secund\xE1ria. Crescendum (Chakram): Posiciona uma atalaia que dispara com sua arma secund\xE1ria.", recarga: [9, 9, 9, 9, 9, 9] }, W: { nome: "Fase", descricao: "Campeao17 troca a arma principal por sua arma secund\xE1ria, substituindo seu ataque b\xE1sico e a habilidade ativada.", recarga: [0.8, 0.8, 0.8, 0.8, 0.8, 0.8] }, E: { nome: "Sistema de Ordena\xE7\xE3o de Armas", descricao: "Campeao17 n\xE3o tem uma terceira habilidade. Este espa\xE7o mostra a pr\xF3xima arma que Alune conceder\xE1 a ele. A ordem das armas \xE9 fixa, mas pode variar ao longo da partida. Quando uma arma estiver sem muni\xE7\xE3o, ela volta para o fim da sequ\xEAncia.", recarga: [0, 0, 0, 0, 0, 0] }, R: { nome: "Vig\xEDlia do Plenil\xFAnio", descricao: "Dispara uma rajada concentrada de luar que explode ao atingir Campe\xF5es inimigos. Aplica o efeito \xFAnico da arma principal de Campeao17.", recarga: [120, 110, 100] } }, skins: [{ num: 0, nome: "Campeao17" }, { num: 1, nome: "Campeao17 Emiss\xE1rio da Escurid\xE3o" }, { num: 30, nome: "Campeao17 HEARTSTEEL" }, { num: 40, nome: "Campeao17 Termas do Florescer Espiritual de Prest\xEDgio" }] };

// dados-Campeao149.js
var a7 = { versao: "16.19.1", campeao: { nome: "Campeao149", titulo: "a Mestra das Cordas", lore: "Campeao149 \xE9 um dos maiores prod\xEDgios em etwahl de cordas em Cidade03, falando somente atrav\xE9s de seus acordes graciosos e de suas \xE1rias vibrantes. Seu comportamento refinado cativou os nobres, apesar de muitos suspeitarem que suas melodias fascinantes realmente emanem magia, um tabu em Cidade03. Silenciosa com desconhecidos, mas compreendida de alguma forma por companheiros pr\xF3ximos, Campeao149 dedilha suas harmonias n\xE3o somente para aliviar a dor de seus aliados, mas tamb\xE9m para derrubar inimigos desavisados.", stats: { hp: 550, hpperlevel: 91, mp: 340, mpperlevel: 45, movespeed: 325, armor: 26, armorperlevel: 4.2, spellblock: 30, spellblockperlevel: 1.3, attackrange: 550, hpregen: 5.5, hpregenperlevel: 0.55, mpregen: 11.5, mpregenperlevel: 0.4, crit: 0, critperlevel: 0, attackdamage: 49, attackdamageperlevel: 0, attackspeedperlevel: 2.3, attackspeed: 0.644 }, funcoes: ["Support", "Mage"] }, habilidades: { P: { nome: "Power Chord", descricao: "Accelerando: Campeao149 recebe Acelera\xE7\xE3o permanentemente para as Habilidades b\xE1sicas (exceto a ultimate), caso use-as corretamente, at\xE9 um limite. Depois disso, o uso bem-sucedido reduz o Tempo de Recarga restante da ultimate. Power Chord: depois de algumas Habilidades conjuradas, o pr\xF3ximo Ataque de Campeao149 causar\xE1 Dano M\xE1gico adicional e um efeito extra com base na \xFAltima Habilidade b\xE1sica ativada por ela." }, Q: { nome: "Hino do Valor", descricao: "Campeao149 toca o Hino do Valor, conjurando rajadas de som, causando Dano M\xE1gico a dois inimigos pr\xF3ximos, priorizando Campe\xF5es e monstros. Campeao149 recebe uma aura tempor\xE1ria que concede dano adicional no pr\xF3ximo ataque de aliados pr\xF3ximos contra inimigos.", recarga: [8, 8, 8, 8, 8] }, W: { nome: "\xC1ria da Perseveran\xE7a", descricao: "Campeao149 toca a \xC1ria da Perseveran\xE7a, conjurando melodias protetoras, curando a si mesma e a um aliado ferido pr\xF3ximo. Campeao149 recebe uma aura tempor\xE1ria que concede um escudo moment\xE2neo a aliados marcados pela \xE1rea.", recarga: [10, 10, 10, 10, 10] }, E: { nome: "Can\xE7\xE3o da Celeridade", descricao: "Campeao149 toca a Can\xE7\xE3o da Celeridade, concedendo Velocidade de Movimento adicional a aliados pr\xF3ximos. Campeao149 recebe uma aura tempor\xE1ria que concede Velocidade de Movimento adicional a Campe\xF5es aliados marcados pela \xE1rea.", recarga: [14, 14, 14, 14, 14] }, R: { nome: "Crescendo", descricao: "Campeao149 toca o seu melhor acorde, causando Dano M\xE1gico, atordoando Campe\xF5es inimigos e for\xE7ando-os a dan\xE7ar.", recarga: [140, 120, 100] } }, skins: [{ num: 0, nome: "Campeao149" }, { num: 1, nome: "Campeao149 Musa" }, { num: 6, nome: "DJ Campeao149" }, { num: 35, nome: "Campeao149 Guardi\xE3 Estelar" }] };

// dados-Campeao112.js
var a8 = { versao: "16.19.1", campeao: { nome: "Campeao112", titulo: "o Buf\xE3o Demon\xEDaco", lore: "Criado anos atr\xE1s como um brinquedo para um pr\xEDncipe solit\xE1rio, Campeao112, a marionete encantada, agora se deleita com assassinatos e desordem. Corrompido por magia das trevas e pela perda de seu dono querido, o boneco que j\xE1 fora gentil agora encontra prazer somente na mis\xE9ria das pr\xF3prias almas que ele atormenta. Ele usa brinquedos e truques simples para conseguir efeitos mortais, achando os resultados de seus \u201Cjogos\u201D sangrentos hil\xE1rios. E para aqueles que escutam uma risada sombria na calada da noite, o Buf\xE3o Demon\xEDaco pode t\xEA-los marcado como seu pr\xF3ximo brinquedo.", stats: { hp: 630, hpperlevel: 99, mp: 297, mpperlevel: 40, movespeed: 345, armor: 30, armorperlevel: 4, spellblock: 32, spellblockperlevel: 2.05, attackrange: 125, hpregen: 8.5, hpregenperlevel: 0.55, mpregen: 6, mpregenperlevel: 0.35, crit: 0, critperlevel: 0, attackdamage: 63, attackdamageperlevel: 0, attackspeedperlevel: 3, attackspeed: 0.694 }, funcoes: ["Assassin"] }, habilidades: { P: { nome: "Apunhalar", descricao: "Apunhalar: o primeiro ataque do Campeao112 em cada inimigo causa dano a mais (cresce com o n\xEDvel e o Dano de Ataque), e o ataque que sai do Enganar tamb\xE9m, sempre cr\xEDtico." }, Q: { nome: "Enganar", descricao: "Campeao112 fica Invis\xEDvel e se teleporta para o local-alvo. Seu primeiro ataque enquanto est\xE1 Invis\xEDvel \xE9 fortalecido, causando dano adicional e cr\xEDtico ao atingir o inimigo por tr\xE1s.", recarga: [13, 12.5, 12, 11.5, 11] }, W: { nome: "Caixinha-Surpresa", descricao: "Campeao112 cria uma Caixinha-Surpresa escondida. Quando ativada, ela causar\xE1 temor e atacar\xE1 inimigos pr\xF3ximos.", recarga: [15, 15, 15, 15, 15] }, E: { nome: "Veneno de Dois Gumes", descricao: "As facas de Campeao112 envenenam alvos passivamente ao contato, reduzindo sua Velocidade de Movimento. Ele pode arremess\xE1-las para causar dano e envenenar o alvo. A faca arremessada causa dano adicional se a Vida do alvo estiver abaixo de 30%.", recarga: [8, 8, 8, 8, 8] }, R: { nome: "Alucina\xE7\xF5es", descricao: "Campeao112 cria uma ilus\xE3o de si mesmo pr\xF3xima a ele, que pode atacar inimigos pr\xF3ximos (causa dano reduzido a torres). Ao morrer, ela explode, fazendo surgir tr\xEAs Caixinhas-Surpresa e causando dano a todos os inimigos pr\xF3ximos.", recarga: [100, 90, 80] } }, skins: [{ num: 0, nome: "Campeao112" }, { num: 2, nome: "Campeao112 Bobo da Corte" }, { num: 8, nome: "Campeao112 Estrela Negra" }, { num: 71, nome: "Campeao112 Pandem\xF4nio de Prest\xEDgio" }] };

// dados-Campeao71.js
var a9 = { versao: "16.19.1", campeao: { nome: "Campeao71", titulo: "o Acossador da Alcateia", lore: "Campeao71 \xE9 um feroz ca\xE7ador de trof\xE9us vastaya que gosta da emo\xE7\xE3o proporcionada pela ca\xE7a e pelo abate de criaturas perigosas. Ele vasculha o mundo em busca das feras mais perigosas que pode encontrar, procurando principalmente por Kha'Zix, a criatura do vazio que arrancou seu olho. Campeao71 n\xE3o persegue suas presas por fome nem por gl\xF3ria, mas pela simples beleza da ca\xE7ada.", stats: { hp: 590, hpperlevel: 104, mp: 4, mpperlevel: 0, movespeed: 345, armor: 34, armorperlevel: 4.2, spellblock: 32, spellblockperlevel: 2.05, attackrange: 125, hpregen: 6, hpregenperlevel: 0.5, mpregen: 0, mpregenperlevel: 0, crit: 0, critperlevel: 0, attackdamage: 68, attackdamageperlevel: 0, attackspeedperlevel: 3, attackspeed: 0.667 }, funcoes: ["Assassin", "Fighter"] }, habilidades: { P: { nome: "Predador Oculto", descricao: "Campeao71 n\xE3o usa mana: cada habilidade d\xE1 1 de Ferocidade (at\xE9 4), e com 4 a pr\xF3xima Selvageria, Rugido de Batalha ou Boleadeiras sai aprimorada. A cada 6 segundos no Rift (10 em Mundo), o pr\xF3ximo ataque \xE9 um salto at\xE9 o alvo, com dano a mais e 1 de Ferocidade; saindo da camuflagem do Furor da Ca\xE7ada, o salto vem na hora." }, Q: { nome: "Selvageria", descricao: "O pr\xF3ximo Ataque de Campeao71 desfere uma punhalada brutal que causa dano adicional. Efeito de Ferocidade: causa dano aumentado e concede Velocidade de Ataque.", recarga: [0.25, 0.25, 0.25, 0.25, 0.25] }, W: { nome: "Rugido de Batalha", descricao: "Campeao71 solta um rugido de batalha, causando dano aos inimigos e curando parte do dano que ele tenha recebido recentemente. Efeito de Ferocidade: quebra efeitos de Controle de Grupo.", recarga: [0.25, 0.25, 0.25, 0.25, 0.25] }, E: { nome: "Boleadeiras", descricao: "Campeao71 arremessa sua boleadeira, reduzindo a velocidade do primeiro alvo atingido por um curto per\xEDodo. Efeito de Ferocidade: enra\xEDza o alvo.", recarga: [0.25, 0.25, 0.25, 0.25, 0.25] }, R: { nome: "Furor da Ca\xE7ada", descricao: "Campeao71 ativa seus instintos predat\xF3rios, ficando Camuflado e revelando o campe\xE3o inimigo mais pr\xF3ximo a ele em um amplo raio ao seu redor. Durante o Furor da Ca\xE7ada, Campeao71 recebe Velocidade de Movimento e pode saltar no inimigo perseguido para reduzir sua armadura, mesmo sem estar no arbusto.", recarga: [100, 90, 80] } }, skins: [{ num: 0, nome: "Campeao71" }, { num: 1, nome: "Campeao71 Ca\xE7ador de Cabe\xE7as" }, { num: 15, nome: "Rengato" }, { num: 8, nome: "Mech Campeao71" }] };

